const updateLocalDetrito = (items, id, updates) => {
  return items.map((item) => (item.id === id ? { ...item, ...updates } : item));
};

const removeLocalDetrito = (items, id) => {
  return items.filter((item) => item.id !== id);
};

module.exports = {
  updateLocalDetrito,
  removeLocalDetrito,
};
